$$
\begin{aligned}
\phi^2 &= \left( \frac{\sqrt{5} + 1}{2} \right)^2
\text{ 1. Apply the exponent to both the numerator and the denominator.}\\
&= \frac{(\sqrt{5} + 1)^2}{2^2} 
\text{  2. Expand the numerator using the perfect square formula:} (a+b)^2 = a^2 + 2ab + b^2. \\
&= \frac{(\sqrt{5})^2 + 2(\sqrt{5})(1) + 1^2}{4} 
\text{ 3. Simplify the squared terms: } (\sqrt{5})^2=5 \text{ and } 1^2=1. \\
&= \frac{5 + 2\sqrt{5} + 1}{4} 
\text{ 4. Combine the rational terms (5 and 1)in the numerator.} \\
&= \frac{6 + 2\sqrt{5}}{4} 
\text{ 5. Factor out the common factor of 2 in the numerator.} \\
&= \frac{2(3 + \sqrt{5})}{4} 
\text{ 6. Cancel the common factor of 2 from the numerator and the denominator.}\\
&= \frac{3 + \sqrt{5}}{2}
\end{aligned}
$$

$$
\begin{aligned}
\frac{1}{\sqrt{3} - \sqrt{2}} &= \frac{1}{\sqrt{3} - \sqrt{2}} \times \frac{\sqrt{3} + \sqrt{2}}{\sqrt{3} + \sqrt{2}} \text{ ( Multiply the numerator and the denominator by the conjugate of the denominator:} 
(\sqrt{3} + \sqrt{2}).) \\
&= \frac{1(\sqrt{3} + \sqrt{2})}{(\sqrt{3} - \sqrt{2})(\sqrt{3} + \sqrt{2})} \text{  (Apply the difference of two squares formula to the denominator:}(a - b)(a + b) = a^2 - b^2. )\\
&= \frac{\sqrt{3} + \sqrt{2}}{(\sqrt{3})^2 - (\sqrt{2})^2} \text{ ( Simplify the squared terms in the denominator:} 
\quad(\sqrt{3})^2 = 3 \text{ and } (\sqrt{2})^2 = 2. )\\
&= \frac{\sqrt{3} + \sqrt{2}}{3 - 2} \text{ ( Subtract the values in the denominator.)}\\ 
&= \frac{\sqrt{3} + \sqrt{2}}{1} \text{ ( Any number divided by 1 is itself.)} \\
&= \sqrt{3} + \sqrt{2}
\end{aligned}
$$
